"""Gym's part of the Judge phase. Standard library only.

Two jobs, one per kind of Gym artifact:

- A **manifest** is judged by NeMo Gym itself: ``gym env validate <name>`` checks
  the workload's config, components, and data files without starting a service.
  ``run_gym`` is the one place this skill calls the ``gym`` CLI, and Solve reuses it.
- A **Gym extension task** is judged by Harbor, after ``convert`` renders it as a
  plain Harbor task directory. Harbor does the judging; this only gives it tasks
  it can read. Output goes to a caller-owned scratch directory outside the
repository, so discovery still writes nothing to the user's checkout.

The rendering follows the contract the Gym authoring prototype states: a task has
exactly one of ``tests/test.sh`` or ``tests/verifier.py``; ``verify()`` receives
the workspace path, plus the row's ``task_data`` for a parameterized task, and
returns the reward; each ``tasks.jsonl`` row fills ``{{ task_data.<key> }}``
placeholders in ``instruction.template.md``. Gym has not shipped its own renderer,
so the generated ``tests/test.sh`` is discovery's stand-in, which lets Harbor judge
everything else about the task.
"""

from __future__ import annotations

import json
import re
import shutil
import subprocess
import tomllib
from dataclasses import dataclass
from pathlib import Path

from providers.gym._explore import PARAMETERIZED

_GYM_TIMEOUT_SEC = 1800
_BRIEF_CHARS = 300


@dataclass(frozen=True)
class GymRun:
    """One ``gym`` CLI run: the JSON report it printed, or why it did not finish."""

    report: dict | None = None
    error: str | None = None

    @property
    def completed(self) -> bool:
        return self.error is None


def validate(gym: str, name: str, kind: str, repo_root: Path) -> GymRun:
    """Have NeMo Gym validate one manifest workload without starting services."""
    return run_gym(gym, ["env", "validate", name, "--kind", kind, "--json"], repo_root)


def validate_command(repo_root: Path, name: str, kind: str) -> str:
    """Return the command that reproduces one validation."""
    return "cd {} && gym env validate {} --kind {}".format(repo_root, name, kind)


def run_gym(gym: str, args: list[str], repo_root: Path) -> GymRun:
    """Run the ``gym`` CLI from the repository root, where Gym finds workloads by name, and read its JSON."""
    try:
        completed = subprocess.run(
            # env(1) runs gym with the inherited environment plus one setting: COLUMNS keeps Rich from
            # wrapping Gym's error messages at the terminal width, which would split file paths.
            ["env", "COLUMNS=10000", gym, *args],
            cwd=repo_root,
            stdin=subprocess.DEVNULL,
            capture_output=True,
            text=True,
            timeout=_GYM_TIMEOUT_SEC,
            check=False,
        )
    except subprocess.TimeoutExpired:
        return GymRun(error="NeMo Gym did not finish within {} minutes.".format(_GYM_TIMEOUT_SEC // 60))
    except OSError as exc:
        return GymRun(error="Cannot start NeMo Gym: {}".format(exc))

    command = "gym {}".format(" ".join(args[:2]))
    if completed.returncode:
        lines = [line.strip() for line in (completed.stderr + completed.stdout).splitlines() if line.strip()]
        starts = [index for index, line in enumerate(lines) if line.startswith("Error")]
        # Gym continues an error on the lines after it, such as the paths it searched.
        detail = " ".join(lines[starts[-1] :]) if starts else lines[-1] if lines else "no output"
        if len(detail) > _BRIEF_CHARS:
            detail = detail[: _BRIEF_CHARS - 3] + "..."
        return GymRun(error="{} exited with code {}: {}".format(command, completed.returncode, detail))
    for line in reversed(completed.stdout.splitlines()):
        if line.startswith("{"):
            try:
                report = json.loads(line)
            except json.JSONDecodeError:
                break
            if isinstance(report, dict):
                return GymRun(report=report)
            break
    return GymRun(error="{} succeeded but printed no JSON report.".format(command))


_PLACEHOLDER = re.compile(r"\{\{\s*task_data\.([A-Za-z_][A-Za-z0-9_]*)\s*\}\}")
_UNSAFE_NAME = re.compile(r"[^A-Za-z0-9._-]")
_SOURCE_ONLY = ("tasks.jsonl", "instruction.template.md")

_LAUNCHER = """#!/usr/bin/env bash
# Generated by Eval Author discovery from tests/verifier.py.
set -u
mkdir -p /logs/verifier
python3 - <<'PY'
import asyncio, importlib.util, inspect, json, os, pathlib

tests = pathlib.Path("/tests")
spec = importlib.util.spec_from_file_location("gym_task_verifier", tests / "verifier.py")
module = importlib.util.module_from_spec(spec)
spec.loader.exec_module(module)
args = [pathlib.Path({workdir!r} or os.getcwd())]
task_data = tests / "task_data.json"
if task_data.is_file():
    args.append(json.loads(task_data.read_text(encoding="utf-8")))
reward = module.verify(*args)
if inspect.isawaitable(reward):
    reward = asyncio.run(reward)
pathlib.Path("/logs/verifier/reward.txt").write_text("{{}}\\n".format(float(reward)))
PY
"""


class ConversionError(Exception):
    """A Gym task that cannot be rendered, with a message naming the defect."""


@dataclass(frozen=True)
class ConvertedTask:
    """One rendered Harbor task and the name it carries in the report."""

    name: str
    path: Path


def convert(task_dir: Path, kind: str, scratch: Path) -> list[ConvertedTask]:
    """Render one Gym extension task directory into Harbor task directories under ``scratch``."""
    tests = task_dir / "tests"
    if (tests / "test.sh").is_file() and (tests / "verifier.py").is_file():
        raise ConversionError(
            "{} has both tests/test.sh and tests/verifier.py; keep exactly one.".format(task_dir.name)
        )
    if kind != PARAMETERIZED:
        target = scratch / task_dir.name
        _copy(task_dir, target)
        return [ConvertedTask(task_dir.name, target)]

    template = _read(task_dir / "instruction.template.md")
    converted: list[ConvertedTask] = []
    seen: set[str] = set()
    for number, line in enumerate(_read(task_dir / "tasks.jsonl").splitlines(), start=1):
        if not line.strip():
            continue
        task_id, task_data = _row(line, number)
        name = _UNSAFE_NAME.sub("-", task_id)
        if name in seen:
            raise ConversionError("tasks.jsonl line {} repeats task_id {!r}.".format(number, task_id))
        seen.add(name)
        target = scratch / task_dir.name / name
        _copy(task_dir, target)
        (target / "instruction.md").write_text(_render(template, task_data, number), encoding="utf-8")
        (target / "tests").mkdir(exist_ok=True)
        (target / "tests" / "task_data.json").write_text(json.dumps(task_data), encoding="utf-8")
        converted.append(ConvertedTask(name, target))
    if not converted:
        raise ConversionError("tasks.jsonl in {} holds no task rows.".format(task_dir.name))
    return converted


def _copy(task_dir: Path, target: Path) -> None:
    shutil.copytree(
        task_dir,
        target,
        symlinks=True,
        ignore=shutil.ignore_patterns("__pycache__", *_SOURCE_ONLY),
    )
    verifier = target / "tests" / "verifier.py"
    if verifier.is_file():
        launcher = target / "tests" / "test.sh"
        launcher.write_text(_LAUNCHER.format(workdir=_workdir(task_dir)), encoding="utf-8")
        launcher.chmod(0o755)


def _workdir(task_dir: Path) -> str:
    try:
        config = tomllib.loads((task_dir / "task.toml").read_text(encoding="utf-8"))
    except (OSError, UnicodeError, tomllib.TOMLDecodeError):
        return ""
    environment = config.get("environment")
    workdir = environment.get("workdir") if isinstance(environment, dict) else None
    return workdir if isinstance(workdir, str) else ""


def _read(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8")
    except (OSError, UnicodeError) as exc:
        raise ConversionError("Cannot read {}: {}.".format(path.name, exc)) from exc


def _row(line: str, number: int) -> tuple[str, dict]:
    try:
        row = json.loads(line)
    except json.JSONDecodeError as exc:
        raise ConversionError("tasks.jsonl line {} is not JSON: {}.".format(number, exc.msg)) from exc
    task_id = row.get("task_id") if isinstance(row, dict) else None
    task_data = row.get("task_data") if isinstance(row, dict) else None
    if not isinstance(task_id, str) or not task_id.strip() or not isinstance(task_data, dict):
        raise ConversionError(
            "tasks.jsonl line {} needs a nonempty string task_id and an object task_data.".format(number)
        )
    return task_id, task_data


def _render(template: str, task_data: dict, number: int) -> str:
    missing = sorted({key for key in _PLACEHOLDER.findall(template) if key not in task_data})
    if missing:
        raise ConversionError("tasks.jsonl line {} has no task_data for {}.".format(number, ", ".join(missing)))
    return _PLACEHOLDER.sub(lambda match: str(task_data[match.group(1)]), template)
